/**
 * Generate 540 SFT domain knowledge training samples for Vortex.
 * Covers content strategy, brand voice, analytics, SEO/SEM,
 * copywriting, social media strategy, and growth marketing.
 */
export async function generate(): Promise<SFTLine[]> {
  const lines: SFTLine[] = [];

  const allPools = [
    ...CONTENT_STRATEGY,
    ...BRAND_VOICE,
    ...ANALYTICS,
    ...SEO_SEM,
    ...COPYWRITING,
    ...SOCIAL_MEDIA,
    ...GROWTH,
  ];

  // Add all handcrafted samples
  for (const sample of allPools) {
    lines.push({
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: sample.user },
        { role: 'assistant', content: sample.assistant },
      ],
    });
  }

  // Generate industry-specific variations to reach 540+
  const industries = [
    "e-commerce fashion brand",
    "B2B SaaS company",
    "health and wellness startup",
    "fintech app",
    "education platform",
    "real estate agency",
    "restaurant chain",
    "consulting firm",
    "creator economy tool",
    "nonprofit organization",
  ];

  const domainQuestions = [
    { q: "What content pillars should I focus on?", domain: "content_strategy" },
    { q: "How do I find the right brand voice?", domain: "brand_voice" },
    { q: "Which analytics metrics should I prioritize?", domain: "analytics" },
    { q: "How do I improve my organic search rankings?", domain: "seo" },
    { q: "Write me a compelling headline for my product.", domain: "copywriting" },
    { q: "Which social platforms should I focus on?", domain: "social" },
    { q: "How do I reduce churn and improve retention?", domain: "growth" },
    { q: "What should my email marketing strategy look like?", domain: "copywriting" },
    { q: "How do I build authority in my niche through content?", domain: "content_strategy" },
    { q: "What does a good marketing dashboard look like for me?", domain: "analytics" },
    { q: "How should I approach competitor analysis?", domain: "seo" },
    { q: "What growth levers should I pull first?", domain: "growth" },
    { q: "How do I create a referral engine?", domain: "growth" },
    { q: "How do I optimize my landing page conversion?", domain: "copywriting" },
    { q: "What's my ideal content mix across channels?", domain: "social" },
    { q: "How do I build a messaging framework for my brand?", domain: "brand_voice" },
    { q: "What does my ideal customer journey look like?", domain: "analytics" },
    { q: "How do I create content that ranks and converts?", domain: "seo" },
    { q: "What's the best way to nurture leads through email?", domain: "copywriting" },
    { q: "How should I structure my marketing team?", domain: "growth" },
    { q: "How do I measure the effectiveness of my brand campaigns?", domain: "analytics" },
    { q: "What content formats perform best for my industry?", domain: "content_strategy" },
    { q: "How do I build community around my brand?", domain: "social" },
    { q: "What's my competitive advantage in positioning?", domain: "brand_voice" },
    { q: "How do I create a content engine that scales?", domain: "content_strategy" },
    { q: "What A/B tests should I run first?", domain: "analytics" },
    { q: "How do I write ad copy that stands out?", domain: "copywriting" },
    { q: "How should I approach influencer partnerships?", domain: "social" },
    { q: "What does a sustainable growth strategy look like?", domain: "growth" },
    { q: "How do I build topical authority for SEO?", domain: "seo" },
    { q: "What tone should my brand strike on social media?", domain: "brand_voice" },
    { q: "How do I create a viral content strategy?", domain: "social" },
    { q: "What should my content distribution strategy be?", domain: "content_strategy" },
    { q: "How do I track attribution across channels?", domain: "analytics" },
    { q: "What's the most efficient way to produce content?", domain: "content_strategy" },
    { q: "How do I write copy that builds trust?", domain: "copywriting" },
    { q: "What growth experiments should I prioritize?", domain: "growth" },
    { q: "How do I improve my email deliverability?", domain: "copywriting" },
    { q: "What link building strategies work in my industry?", domain: "seo" },
    { q: "How do I turn customers into brand advocates?", domain: "growth" },
    { q: "What brand archetype fits my business?", domain: "brand_voice" },
    { q: "How do I create an editorial calendar that my team follows?", domain: "content_strategy" },
    { q: "How do I set up proper conversion tracking?", domain: "analytics" },
    { q: "What CTA strategies drive the most clicks?", domain: "copywriting" },
  ];

  const domainResponses: Record<string, (industry: string) => string> = {
    content_strategy: (ind) =>
      `For a ${ind}, your content strategy needs to be built on audience behavior data, not assumptions. Start by identifying the three to five questions your ideal customer asks before buying. Those become your content pillars. Map each pillar to a buyer journey stage, assign formats that match platform strengths, and set a publishing cadence you can sustain. I'd audit what your competitors are publishing, find the gaps, and own those topics. Build one complete topic cluster before expanding. Consistency and specificity beat volume every time.`,
    brand_voice: (ind) =>
      `For a ${ind}, brand voice starts with your belief system. What do you stand for that your competitors don't? That belief shapes your tone, vocabulary, and communication style. I'd build a voice guide with three core attributes — each with a spectrum showing the boundary. Include word lists, writing samples, and channel-specific tone adjustments. Then train your team with before-and-after examples. The voice should feel like a specific person your audience would want to have a conversation with. Generic brand voice is worse than no brand voice at all.`,
    analytics: (ind) =>
      `For a ${ind}, I'd set up a three-tier measurement framework. Leading indicators measured weekly: traffic, engagement rate, email growth. Conversion indicators measured monthly: lead generation, pipeline value, conversion rates between funnel stages. Lagging indicators measured quarterly: CAC, LTV, content ROI, and organic share of voice. Build a single-page dashboard that shows all three tiers. The biggest mistake I see is measuring everything and acting on nothing. Pick the three metrics most correlated with revenue and optimize relentlessly for those. Everything else is context.`,
    seo: (ind) =>
      `For a ${ind}, SEO strategy starts with search intent mapping. What queries signal buying intent versus research intent in your space? Build content that matches each intent type. For technical SEO, ensure your site loads under 2.5 seconds, is mobile-first, and has clean internal linking. For content SEO, build topic clusters around your core keywords with pillar pages linking to detailed subtopic articles. For authority, earn backlinks through original research, data studies, and genuinely useful tools. SEO is a compounding investment — the earlier you start building the asset, the wider the moat becomes.`,
    copywriting: (ind) =>
      `For a ${ind}, copywriting effectiveness comes from understanding your customer's internal monologue. What are they thinking and feeling at the moment they encounter your copy? Write to that mental state. Use the PAS framework for problem-aware audiences: name the pain, amplify the consequences, present your solution. Use AIDA for unaware audiences: grab attention, build interest, create desire, prompt action. Every headline makes a promise. Every body copy delivers proof. Every CTA reduces friction. Test relentlessly — the data will teach you more about your audience than any persona document.`,
    social: (ind) =>
      `For a ${ind}, social media strategy should be platform-selective, not platform-exhaustive. Go deep on the one or two platforms where your audience is most active and most receptive. Create platform-native content — same core insight, different delivery for each channel. Build a content calendar that balances pillar content, engagement content, and promotional content in a 60/30/10 ratio. Invest in community management — responding to every comment within four hours signals to both the algorithm and your audience that you're present. Track saves and shares over likes. Those are the signals that predict growth.`,
    growth: (ind) =>
      `For a ${ind}, growth strategy starts with understanding your unit economics. What's your CAC, LTV, and payback period? Those numbers determine which growth levers are viable. If LTV is high and CAC is low, invest in scaling acquisition. If LTV is low, focus on retention and expansion revenue first. Build a growth model that maps your key metrics and shows which inputs have the highest leverage. Then run experiments against those leverage points in weekly sprints. Document everything. The compound effect of running 10 growth experiments per month for a year is a proprietary playbook no competitor can replicate.`,
  };

  for (const industry of industries) {
    for (const dq of domainQuestions) {
      const contextualUser = `I run a ${industry}. ${dq.q}`;
      const response = domainResponses[dq.domain]?.(industry) ?? domainResponses['content_strategy']!(industry);
      lines.push({
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: contextualUser },
          { role: 'assistant', content: response },
        ],
      });
    }
  }

  return lines.slice(0, SAMPLE_COUNT);
}
